//! A call this project made, decoded by the same code that reads other
//! people's.
//!
//! Up to now every recording here was somebody else's, which meant any
//! disagreement between the code and a capture could be blamed on either. A
//! call generated by these modems and then read back by the same receiver
//! closes that: if it decodes, the transmitter and the receiver agree, and if
//! it does not, they do not, and neither can be blamed on a Conexant softmodem
//! from 2005.
//!
//! Being able to write one out also means the scope has something of its own
//! to look at, and a person can listen to what a V.22bis call sounds like
//! without owning a modem.

use datapump::v22bis::{Channel, Receiver};
use ec::hdlc::{Decoder, Fcs};
use modem::{Modem, State};

const FS: f64 = 16_000.0;

/// Run a call and return everything a tap on the two-wire line would have
/// heard, both directions summed.
fn record(carrier: &str, text: &str, seconds: f64) -> Vec<f32> {
    let mut caller = Modem::new(FS);
    let mut host = Modem::new(FS);
    for m in [&mut caller, &mut host] {
        // Automode off. These are about one modulation over one line, and
        // with it on the modem would negotiate its way to whichever
        // modulation the two ends liked best -- which is the right
        // answer to a different question.
        for b in format!("AT+MS={carrier},0\r").bytes() {
            m.feed_dte(b);
        }
        m.take_dte();
    }
    for b in b"ATA\r" {
        host.feed_dte(*b);
    }
    for b in b"ATD5551234\r" {
        caller.feed_dte(*b);
    }

    let mut line = Vec::new();
    let (mut from_caller, mut from_host) = (0.0, 0.0);
    let (mut settled, mut spoken) = (f64::NAN, false);
    for i in 0..(seconds * FS) as usize {
        let (a, b) = (from_caller, from_host);
        from_caller = caller.step(b);
        from_host = host.step(a);
        line.push(((a + b) * 0.5) as f32);
        caller.take_dte();
        host.take_dte();

        let up = caller.state() == State::Data && host.state() == State::Data;
        if up && settled.is_nan() {
            settled = i as f64 / FS;
        }
        if up && !spoken && i as f64 / FS > settled + 1.5 {
            spoken = true;
            for byte in text.bytes() {
                host.feed_dte(byte);
            }
        }
    }
    line
}

#[test]
fn a_recording_of_our_own_call_decodes_the_way_a_real_one_does() {
    // Read back exactly as the V.22bis vector test reads the Conexant capture:
    // demodulate the high channel, deframe what comes out, and look in the
    // frames whose check sequence holds.
    let greeting = "Welcome to phl6-dial1.popsite.net";
    let line = record("V22B", greeting, 20.0);

    let mut rx = Receiver::new(Channel::Calling, FS);
    let mut decoder = Decoder::new(Fcs::Bits16);
    let mut text = String::new();
    let (mut good, mut failed) = (0usize, 0usize);
    for s in &line {
        rx.feed(f64::from(*s));
        for bit in rx.take_bits() {
            match decoder.feed(bit) {
                Some(Ok(frame)) => {
                    good += 1;
                    // Information frames have the low bit of the control field
                    // clear; everything else is supervisory and carries no text.
                    if frame.len() > 2 && frame[1] & 1 == 0 {
                        text.push_str(&String::from_utf8_lossy(&frame[2..]));
                    }
                }
                Some(Err(ec::hdlc::FrameError::BadFcs)) => failed += 1,
                _ => {}
            }
        }
    }

    assert!(good >= 4, "only {good} frames survived their check sequence");
    assert_eq!(failed, 0, "{failed} frames were corrupted on a clean line");
    assert!(
        text.contains(greeting),
        "the greeting did not come back out of the recording; got {text:?}"
    );
}

#[test]
fn a_recording_has_to_be_scaled_before_it_will_fit() {
    // Not a formality. Pulse shaping sums the tails of several symbols, so a
    // modem's peak runs well above its average, and two modems on one pair sum
    // again: measured, a V.22bis call between two of these reaches about one
    // and a half. Written out as it stands, every peak comes back clipped and
    // every measurement made from the file afterwards is of something else.
    let mut line = record("V22B", "hello", 12.0);
    let raw = line.iter().fold(0.0f32, |m, s| m.max(s.abs()));
    assert!(
        raw > 1.0,
        "the line peaked at {raw}, so this test is no longer testing anything"
    );

    let gain = modem::fit_to_scale(&mut line, 0.9);
    assert!(gain < 1.0, "nothing was scaled");
    let peak = line.iter().fold(0.0f32, |m, s| m.max(s.abs()));
    assert!(peak <= 0.9001, "still {peak} after scaling");
    assert!(peak > 0.5, "scaled away to {peak}");
}
